"""Generate docs/rules.md (a rule catalogue for business readers) from config/rules/."""

from pathlib import Path

from rav.rules.models import RuleConfig

RULES_DOC = Path("docs/rules.md")


def render_rules_md(rules: list[RuleConfig]) -> str:
    out = [
        "# Rule catalogue",
        "",
        "Generated by `rav docs` from `config/rules/*.yaml`. Do not edit by hand.",
        "All data in this repository is synthetic.",
        "",
        "Simplified balance used throughout: `balance = premium - commission - claims_paid`.",
        "",
        "| ID | Name | Severity | Checks for defect | Implementation |",
        "|---|---|---|---|---|",
    ]
    for r in rules:
        impl = f"SQL `{r.sql_file}`" if r.type == "sql" else f"Python `{r.function}`"
        out.append(f"| {r.id} | {r.name} | {r.severity} | {r.detects} | {impl} |")
    for r in rules:
        out += ["", f"## {r.id} - {r.name}", "", " ".join(r.description.split())]
        if r.params:
            tolerances = ", ".join(f"`{k}` = {v}" for k, v in r.params.items())
            out += ["", f"Tolerances: {tolerances}"]
        if not r.enabled:
            out += ["", "_Disabled._"]
    return "\n".join(out) + "\n"
